// frontend/src/components/AutomationMetrics/AutoRegression.js
import React from "react";
import "../../styles/roiTabs.css";
import "../../styles/RecordEntry.css";

export default function AutoRegression() {
  return (
    <div className="tab-wrap">
      
      <div className="tab-section tab-section-yellow">RELEASE REGRESSION</div>
      <div className="grid-2">
        <div className="text-gray-600">
          auto regression.
        </div>
      </div>
    </div>
  );
}
